   if(v==null||v.root!=Full(CPPPhase6ShoppingBuildPolicy.Root)||v.stage!=Full(Project)||v.candidate!=Full(Path.Combine(v.root,CPPPhase6ShoppingBuildPolicy.CandidateRelative))||v.action!=action)throw new InvalidOperationException("Attested exact action/boundaries");
   string[] names={".shopping-root-pins.tsv",".shopping-stage-pins.tsv",".shopping-meta-allowlist.json",".shopping-builder-input.json"};string[] hashes={v.rootPinsSHA,v.stagePinsSHA,v.metaAllowlistSHA,v.builderInputSHA};for(int i=0;i<names.Length;i++)if(Phase5BuildPolicy.Hash(Path.Combine(Project,names[i]))!=hashes[i])throw new InvalidOperationException("Attested data drift");
   var source=Pins(Path.Combine(Project,names[0]));var staged=Pins(Path.Combine(Project,names[1]));
   var allowance=JsonUtility.FromJson<MetaAllowance>(File.ReadAllText(Path.Combine(Project,names[2])));if(allowance==null||allowance.assets==null||allowance.folders==null)throw new InvalidOperationException("Explicit file/folder metadata allowlist required");
   CPPPhase6ShoppingBuildPolicy.AdmitClosure(v.root,Project,source,staged,allowance.assets,allowance.folders,action);return v;
  }
