  static Input Read(){var v=JsonUtility.FromJson<Input>(File.ReadAllText(Path.Combine(Project,".shopping-builder-input.json")));if(v==null||v.schemaVersion!=1||v.generation!=Generation||v.files==null||v.files.Length!=109||v.profile==null||v.profile.generationId!=Generation||v.profile.printingId!="base-en-unlimited1999"||v.profile.cards.Length!=101||v.profile.wrapperFronts.Length!=3)throw new InvalidOperationException("Frozen Base input shape");var seen=new HashSet<string>(StringComparer.Ordinal);foreach(var f in v.files){if(!seen.Add(f.targetPath)||!f.targetPath.StartsWith("Assets/Supplied/PerformanceBase/generations/"+Generation+"/",StringComparison.Ordinal)||f.targetPath.Contains("..")||f.targetPath.Contains("\\")||f.targetPath.Contains(":")||f.sourceSha256!=f.copySha256||Phase5BuildPolicy.Hash(Path.Combine(Project,f.targetPath))!=f.copySha256||Phase5BuildPolicy.Hash(Path.Combine(Project,f.sourcePath))!=f.sourceSha256||f.maxTextureSize!=1024||f.mipmaps||!f.readable||f.linear==f.sRGB||f.compression!="Uncompressed"||f.filterMode!="Bilinear"||f.wrapMode!="Clamp")throw new InvalidOperationException("Exact Base byte/import authority");}return v;}
  static void Absent(string path){if(File.Exists(Path.Combine(Project,path))||File.Exists(Path.Combine(Project,path+".meta")))throw new InvalidOperationException("New-only authoring; no overwrite");}
  static Texture2D Tex(string path){if(string.IsNullOrEmpty(path))return null;var value=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(value==null)throw new InvalidOperationException("Missing native texture "+path);return value;}
  static string HashBytes(byte[] bytes){using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static void VerifyPixels(Input input){foreach(var f in input.files){var t=Tex(f.targetPath);var importer=AssetImporter.GetAtPath(f.targetPath) as TextureImporter;if(importer==null||t.width!=f.width||t.height!=f.height||importer.sRGBTexture!=f.sRGB||importer.mipmapEnabled||!importer.isReadable||importer.maxTextureSize!=1024||importer.textureCompression!=TextureImporterCompression.Uncompressed||importer.wrapMode!=TextureWrapMode.Clamp||importer.filterMode!=FilterMode.Bilinear||importer.npotScale!=TextureImporterNPOTScale.None)throw new InvalidOperationException("Native dimensions/import settings");var pixels=t.GetPixels32();var bytes=new byte[checked(f.width*f.height*4)];for(int y=0;y<f.height;y++)for(int x=0;x<f.width;x++){var p=pixels[(f.height-1-y)*f.width+x];int i=(y*f.width+x)*4;bytes[i]=p.r;bytes[i+1]=p.g;bytes[i+2]=p.b;bytes[i+3]=p.a;}if(HashBytes(bytes)!=f.rgbaSha256)throw new InvalidOperationException("Full native RGBA identity with normalized row order");}}
  static readonly string[] ShoppingTypes={"VintageCollector.Runtime.Phase6ShoppingHost","VintageCollector.Presentation.ShoppingPresentation","VintageCollector.Verification.Phase6ShoppingSmokeProbe"};
  static Type ExactType(string name){var types=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType(name,false)).Where(t=>t!=null).ToArray();if(types.Length!=1||!typeof(MonoBehaviour).IsAssignableFrom(types[0]))throw new InvalidOperationException("Reviewed Shopping type must exist before copying: "+name);return types[0];}
  static void Registry(OpeningGame game){if(game.phase5Sets==null||game.phase5Sets.Length!=3)throw new InvalidOperationException("Retained registry configurations");var registry=ApprovedSetRegistry.FromApprovedData(game.phase5Sets.Select(s=>Catalog.FromData(JsonUtility.FromJson<CatalogData>(s.catalogJson.text))).ToArray(),game.phase5Sets.Select(s=>JsonUtility.FromJson<RuleData>(s.modelJson.text)).ToArray());int count=0;foreach(var set in registry.Sets)foreach(var card in set.Catalog.Cards)if(registry.IsCompletionEligible(card.Id)){var w=WantedCard.FromRegistry(registry,card.Id);if(w.Language!="en"||w.Edition!="unlimited"||w.Condition!="Near Mint"||!w.RawUngraded)throw new InvalidOperationException("Wanted authority");count++;}if(count!=227)throw new InvalidOperationException("Exact 227 registry identities");}
  public static void CreateAssets(){Admit("CreateAssets");foreach(string name in ShoppingTypes)ExactType(name);var input=Read();ValidateAssets(input);Registry(Open(OldScene));AssetDatabase.SaveAssets();}
  static void ValidateAssets(Input input){VerifyPixels(input);var p=AssetDatabase.LoadAssetAtPath<NativeBaseMediaProfile>(ProfilePath);var q=input.profile;if(p==null||p.printingId!=q.printingId||p.generationId!=q.generationId||p.displayLabel!=q.displayLabel||p.cards.Length!=101||p.wrapperFronts.Length!=3)throw new InvalidOperationException("Native Base SO identity");for(int i=0;i<101;i++)if(p.cards[i].canonicalId!=q.cards[i].canonicalId||p.cards[i].face!=Tex(q.cards[i].face)||p.cards[i].mask!=Tex(q.cards[i].mask))throw new InvalidOperationException("Native Base card binding");if(p.sharedCardBack!=Tex(q.sharedCardBack)||p.wrapperBack!=Tex(q.wrapperBack)||p.wrapperFrontMask!=Tex(q.wrapperFrontMask)||p.wrapperBackMask!=Tex(q.wrapperBackMask)||!p.wrapperFronts.SequenceEqual(q.wrapperFronts.Select(Tex)))throw new InvalidOperationException("Exact wrapper/back fields");}
  static OpeningGame Open(string path){var scene=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var games=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<OpeningGame>(true)).ToArray();if(games.Length!=1)throw new InvalidOperationException("Exactly one retained controller");return games[0];}
  static Type Probe(string name){var types=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("VintageCollector.Verification."+name,false)).Where(t=>t!=null).ToArray();if(types.Length!=1||!typeof(MonoBehaviour).IsAssignableFrom(types[0]))throw new InvalidOperationException("Native precondition: reviewed runtime probe missing: "+name);return types[0];}
