  static string RetainedFields(UnityEngine.Object value){var rows=new List<string>();var serialized=new SerializedObject(value);var p=serialized.GetIterator();while(p.Next(true)){if(p.propertyPath.StartsWith("m_",StringComparison.Ordinal))continue;string data;switch(p.propertyType){case SerializedPropertyType.Generic:data="container";break;case SerializedPropertyType.ArraySize:data=p.intValue.ToString(System.Globalization.CultureInfo.InvariantCulture);break;case SerializedPropertyType.Integer:data=p.longValue.ToString(System.Globalization.CultureInfo.InvariantCulture);break;case SerializedPropertyType.Boolean:data=p.boolValue?"true":"false";break;case SerializedPropertyType.Float:data=p.doubleValue.ToString("R",System.Globalization.CultureInfo.InvariantCulture);break;case SerializedPropertyType.String:data=p.stringValue;break;case SerializedPropertyType.Enum:data=p.intValue.ToString(System.Globalization.CultureInfo.InvariantCulture);break;case SerializedPropertyType.ObjectReference:if(p.objectReferenceValue==null){if(p.objectReferenceInstanceIDValue!=0)throw new InvalidOperationException("Missing retained reference");data="null";}else{string guid;long id;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(p.objectReferenceValue,out guid,out id))throw new InvalidOperationException("Retained binding must be persistent asset");data=guid+":"+id.ToString(System.Globalization.CultureInfo.InvariantCulture);}break;default:throw new InvalidOperationException("Unsupported retained field kind "+p.propertyType);}rows.Add(p.propertyPath+"|"+p.propertyType+"|"+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(data??"")));}return string.Join("\n",rows);}
  static void RequiredOwners(OpeningGame game){if(game.GetComponent<Phase5CollectionHost>()==null||game.GetComponent<Phase5MediaHost>()==null||game.GetComponent<BinderPresentation>()==null||game.GetComponent<TabletopPresentation>()==null||!game.backgroundOpeningStorage)throw new InvalidOperationException("Retained same-object owners and async storage required");}
  public static void CreateBootstrap(){Admit("CreateBootstrap");var types=ShoppingTypes.Select(ExactType).ToArray();foreach(string path in CPPPhase6ShoppingBuildPolicy.Scenes)Absent(path);var input=Read();ValidateAssets(input);var old=Open(OldScene);RequiredOwners(old);Registry(old);string gameJson=RetainedFields(old),mediaJson=RetainedFields(old.GetComponent<Phase5MediaHost>());if(!AssetDatabase.CopyAsset(OldScene,Scene))throw new IOException("Clone accepted performance scene failed");var game=Open(Scene);RequiredOwners(game);foreach(var component in game.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)))if(component!=null&&component.GetType().FullName=="VintageCollector.Verification.PerformanceSmokeProbe")UnityEngine.Object.DestroyImmediate(component);foreach(var type in types){if(game.GetComponent(type)!=null)throw new InvalidOperationException("New Shopping component already exists");game.gameObject.AddComponent(type);}if(RetainedFields(game)!=gameJson||RetainedFields(game.GetComponent<Phase5MediaHost>())!=mediaJson)throw new InvalidOperationException("Retained opening/media serialized references changed");EditorSceneManager.MarkSceneDirty(game.gameObject.scene);if(!EditorSceneManager.SaveScene(game.gameObject.scene,Scene))throw new IOException("Save Shopping clone");
   var light=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);new GameObject("Shopping startup coordinator").AddComponent<StartupLoadingCoordinator>().heavySceneName="BootstrapShopping";var camera=new GameObject("Startup camera").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;if(!EditorSceneManager.SaveScene(light,CPPPhase6ShoppingBuildPolicy.Startup))throw new IOException("Save lightweight Shopping scene");AssetDatabase.SaveAssets();ValidateScene(input);PrepareRecipeCore();DiskRecipe();}
  static void ValidateScene(Input input){ValidateAssets(input);var old=Open(OldScene);RequiredOwners(old);string gameJson=RetainedFields(old),mediaJson=RetainedFields(old.GetComponent<Phase5MediaHost>());var game=Open(Scene);RequiredOwners(game);Registry(game);if(RetainedFields(game)!=gameJson||RetainedFields(game.GetComponent<Phase5MediaHost>())!=mediaJson)throw new InvalidOperationException("Reopened retained media/wrappers/back/audio/async authority changed");foreach(string name in ShoppingTypes)if(game.GetComponent(ExactType(name))==null)throw new InvalidOperationException("Same GameObject Shopping component required");foreach(var component in game.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)))if(component!=null&&component.GetType().Namespace=="VintageCollector.Verification"&&component.GetType().FullName!="VintageCollector.Verification.Phase6ShoppingSmokeProbe")throw new InvalidOperationException("Old probes forbidden on Shopping clone");var light=EditorSceneManager.OpenScene(CPPPhase6ShoppingBuildPolicy.Startup,OpenSceneMode.Single);var owners=light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<StartupLoadingCoordinator>(true)).ToArray();var components=light.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MonoBehaviour>(true)).ToArray();if(owners.Length!=1||owners[0].heavySceneName!="BootstrapShopping"||components.Length!=1||components[0]!=owners[0])throw new InvalidOperationException("Only dedicated coordinator and camera in light scene");if(AssetDatabase.GetDependencies(CPPPhase6ShoppingBuildPolicy.Startup,true).Any(p=>p.EndsWith(".asset",StringComparison.OrdinalIgnoreCase)||p.EndsWith(".png",StringComparison.OrdinalIgnoreCase)||p.EndsWith(".json",StringComparison.OrdinalIgnoreCase)||p.StartsWith("Assets/Supplied/",StringComparison.Ordinal)))throw new InvalidOperationException("No heavy startup asset dependencies");}
  static void PrepareRecipeCore(){if(PlayerSettings.defaultScreenWidth!=1280||PlayerSettings.defaultScreenHeight!=720||PlayerSettings.fullScreenMode!=FullScreenMode.Windowed||EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Root release defaults required; never rewrite settings");byte[] recipe=CPPPhase6ShoppingBuildPolicy.RecipeBytes(CPPPhase6ShoppingBuildPolicy.Root,Project);EditorBuildSettings.scenes=CPPPhase6ShoppingBuildPolicy.Scenes.Select(s=>new EditorBuildSettingsScene(s,true)).ToArray();File.WriteAllBytes(Path.Combine(Project,CPPPhase6ShoppingBuildPolicy.Settings),recipe);}

  static void DiskRecipe(){if(!File.ReadAllBytes(Path.Combine(Project,CPPPhase6ShoppingBuildPolicy.Settings)).SequenceEqual(CPPPhase6ShoppingBuildPolicy.RecipeBytes(CPPPhase6ShoppingBuildPolicy.Root,Project)))throw new InvalidOperationException("Exact TWO-scene disk recipe required");}
  public static void PrepareReleaseRecipe(){Admit("CreateBootstrap");PrepareRecipeCore();DiskRecipe();}
  public static void BuildWindows(){var a=Admit("BuildWindows");var input=Read();ValidateScene(input);if(PlayerSettings.defaultScreenWidth!=1280||PlayerSettings.defaultScreenHeight!=720||PlayerSettings.fullScreenMode!=FullScreenMode.Windowed||EditorBuildSettings.scenes.Length!=2||!EditorBuildSettings.scenes.Select(s=>s.path).SequenceEqual(CPPPhase6ShoppingBuildPolicy.Scenes)||EditorBuildSettings.scenes.Any(s=>!s.enabled)||EditorUserBuildSettings.development||PlayerSettings.GetScriptingBackend(NamedBuildTarget.Standalone)!=ScriptingImplementation.Mono2x||PlayerSettings.GetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64)||!PlayerSettings.GetGraphicsAPIs(BuildTarget.StandaloneWindows64).SequenceEqual(new[]{GraphicsDeviceType.Direct3D11}))throw new InvalidOperationException("Frozen release recipe required before pins");DiskRecipe();var before=Phase5BuildPolicy.AllInputs(Project);Directory.CreateDirectory(a.candidate);File.WriteAllText(Path.Combine(a.candidate,".shopping-candidate-owner.txt"),"shopping-exact-source-v1\n"+a.root+"\n");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=CPPPhase6ShoppingBuildPolicy.Scenes,target=BuildTarget.StandaloneWindows64,locationPathName=Path.Combine(a.candidate,"VintageCardCollector.exe"),options=BuildOptions.None});CPPPhase6ShoppingBuildPolicy.ExactClosure(Project,before);if(report.summary.result!=BuildResult.Succeeded||report.summary.totalErrors!=0||report.summary.totalWarnings!=0)throw new InvalidOperationException("Native build must have zero warnings/errors");var candidate=new List<Pin>();Phase5BuildPolicy.RequireRegularTree(a.candidate);foreach(string p in Directory.GetFiles(a.candidate,"*",SearchOption.AllDirectories))candidate.Add(new Pin{path=Full(p).Substring(a.candidate.Length+1),sha256=Phase5BuildPolicy.Hash(p)});File.WriteAllText(Path.Combine(Project,".shopping-build-report.json"),JsonUtility.ToJson(new Evidence{passed=true,compilerPins=before.Select(p=>new Pin{path=p.Key,sha256=p.Value}).ToArray()